/* CSS PART 1 OF 2 */

/* DESIGN TOKENS */
:root {
  --ink: #202923;
  --ink-soft: #455148;
  --forest: #293f35;
  --forest-deep: #1d3028;
  --sage: #849486;
  --cream: #f5f3ed;
  --paper: #fffefa;
  --stone: #e6e4db;
  --copper: #bd8057;
  --white: #ffffff;

  --font-display: "Georgia", "Times New Roman", serif;
  --font-body: "Inter", "Segoe UI", Arial, sans-serif;

  --container: 1200px;
  --gutter: clamp(22px, 5vw, 76px);
  --header-height: 86px;

  --radius: 3px;
  --shadow: 0 18px 55px rgba(24, 37, 29, 0.13);
  --transition: 220ms ease;
}

/* RESET */
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 100px;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
textarea,
select {
  font: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

button:focus-visible,
a:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible {
  outline: 3px solid var(--copper);
  outline-offset: 4px;
}

::selection {
  color: var(--white);
  background: var(--forest);
}

/* SHARED TYPOGRAPHY */
h1,
h2,
h3,
p {
  margin-top: 0;
}

h1,
h2,
h3 {
  color: var(--ink);
  font-family: var(--font-display);
  font-weight: 400;
  line-height: 1.12;
  letter-spacing: -0.035em;
}

h1 {
  font-size: clamp(3rem, 6.8vw, 6.5rem);
}

h2 {
  margin-bottom: 22px;
  font-size: clamp(2.35rem, 4.4vw, 4rem);
}

h3 {
  font-size: clamp(1.45rem, 2vw, 1.9rem);
}

p {
  color: var(--ink-soft);
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 19px;
  color: var(--copper);
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.17em;
  line-height: 1.4;
  text-transform: uppercase;
}

.eyebrow::before {
  width: 29px;
  height: 2px;
  background: currentColor;
  content: "";
}

.lead {
  max-width: 650px;
  font-size: clamp(1.05rem, 1.5vw, 1.2rem);
  line-height: 1.85;
}

.section-intro {
  max-width: 670px;
  margin-bottom: 54px;
}

.section-intro p:last-child {
  margin-bottom: 0;
}

/* PAGE LAYOUT */
.container {
  width: min(var(--container), calc(100% - var(--gutter) * 2));
  margin-inline: auto;
}

.section {
  padding-block: clamp(82px, 10vw, 140px);
}

.section--cream {
  background: var(--cream);
}

.section--dark {
  background: var(--forest-deep);
  color: var(--white);
}

.section--dark h2,
.section--dark h3 {
  color: var(--white);
}

.section--dark p {
  color: rgba(255, 255, 255, 0.76);
}

.section--dark .eyebrow {
  color: #d9a47f;
}

/* HEADER AND NAVIGATION */
.site-header {
  position: relative;
  z-index: 20;
  background: var(--paper);
  border-bottom: 1px solid rgba(32, 41, 35, 0.09);
}

.header-inner {
  display: flex;
  min-height: var(--header-height);
  align-items: center;
  justify-content: space-between;
  gap: 28px;
}

.brand {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 14px;
}

.brand-logo {
  width: 66px;
  height: 66px;
  flex: 0 0 auto;
  object-fit: contain;
}

.brand-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
  line-height: 1.2;
}

.brand-name {
  color: var(--forest);
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 700;
}

.brand-subtitle {
  color: var(--ink-soft);
  font-size: 0.64rem;
  font-weight: 700;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.nav-links {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: clamp(17px, 2.5vw, 34px);
}

.nav-links a:not(.button) {
  position: relative;
  padding-block: 8px;
  color: var(--ink-soft);
  font-size: 0.82rem;
  font-weight: 650;
  transition: color var(--transition);
}

.nav-links a:not(.button)::after {
  position: absolute;
  right: 0;
  bottom: 2px;
  left: 0;
  height: 1px;
  background: var(--copper);
  content: "";
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--transition);
}

.nav-links a:not(.button):hover {
  color: var(--forest);
}

.nav-links a:not(.button):hover::after {
  transform: scaleX(1);
}

/* BUTTONS */
.button {
  display: inline-flex;
  min-height: 52px;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 14px 24px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  background: var(--forest);
  color: var(--white);
  cursor: pointer;
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0.065em;
  line-height: 1.2;
  text-align: center;
  text-transform: uppercase;
  transition:
    background var(--transition),
    color var(--transition),
    border-color var(--transition),
    transform var(--transition);
}

.button:hover {
  background: var(--forest-deep);
  transform: translateY(-2px);
}

.button--light {
  background: var(--paper);
  color: var(--forest);
}

.button--light:hover {
  background: var(--cream);
  color: var(--forest-deep);
}

.button--outline {
  border-color: rgba(255, 255, 255, 0.7);
  background: transparent;
  color: var(--white);
}

.button--outline:hover {
  border-color: var(--white);
  background: var(--white);
  color: var(--forest);
}

.button-arrow {
  font-size: 1.1rem;
  line-height: 1;
}

/* FULL-BLEED HERO */
.hero {
  position: relative;
  display: flex;
  min-height: min(780px, calc(100svh - var(--header-height)));
  align-items: center;
  overflow: hidden;
  background: var(--forest-deep);
  color: var(--white);
  isolation: isolate;
}

.hero-image {
  position: absolute;
  z-index: -2;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 48%;
}

.hero::before {
  position: absolute;
  z-index: -1;
  inset: 0;
  background:
    linear-gradient(
      90deg,
      rgba(19, 33, 26, 0.91) 0%,
      rgba(19, 33, 26, 0.78) 38%,
      rgba(19, 33, 26, 0.35) 72%,
      rgba(19, 33, 26, 0.16) 100%
    ),
    linear-gradient(
      0deg,
      rgba(19, 33, 26, 0.35),
      transparent 55%
    );
  content: "";
}

.hero-content {
  width: min(var(--container), calc(100% - var(--gutter) * 2));
  margin-inline: auto;
  padding-block: 105px 115px;
}

.hero .eyebrow {
  color: #e2ad87;
}

.hero h1 {
  max-width: 850px;
  margin-bottom: 26px;
  color: var(--white);
}

.hero-description {
  max-width: 590px;
  margin-bottom: 35px;
  color: rgba(255, 255, 255, 0.88);
  font-size: clamp(1.05rem, 1.5vw, 1.2rem);
  line-height: 1.8;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px;
}

.hero-note {
  margin-top: 34px;
  color: rgba(255, 255, 255, 0.78);
  font-size: 0.76rem;
  font-weight: 650;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

/* COMPANY INTRODUCTION */
.intro-layout {
  display: grid;
  grid-template-columns: 0.95fr 1.05fr;
  align-items: center;
  gap: clamp(45px, 8vw, 110px);
}

.intro-copy {
  max-width: 570px;
}

.intro-copy p {
  line-height: 1.9;
}

.intro-image-wrap {
  position: relative;
  min-height: 480px;
}

.intro-image {
  width: 100%;
  height: 100%;
  min-height: 480px;
  object-fit: cover;
  object-position: center;
}

.intro-caption {
  position: absolute;
  right: -18px;
  bottom: 25px;
  max-width: 250px;
  padding: 22px 25px;
  background: var(--forest);
  color: var(--white);
  font-family: var(--font-display);
  font-size: 1.15rem;
  line-height: 1.4;
}

/* WHY CHOOSE JOSH BROOKS */
.why-layout {
  display: grid;
  grid-template-columns: 0.8fr 1.2fr;
  gap: clamp(45px, 8vw, 100px);
}

.why-heading {
  position: sticky;
  top: 35px;
  align-self: start;
}

.why-heading h2 {
  max-width: 440px;
}

.why-heading p {
  max-width: 400px;
}

.why-points {
  border-top: 1px solid var(--stone);
}

.why-point {
  display: grid;
  grid-template-columns: 54px 1fr;
  gap: 22px;
  padding-block: 30px;
  border-bottom: 1px solid var(--stone);
}

.why-number {
  color: var(--copper);
  font-family: var(--font-display);
  font-size: 1.5rem;
}

.why-point h3 {
  margin-bottom: 9px;
}

.why-point p {
  max-width: 590px;
  margin-bottom: 0;
}

/* ROOFING AND HAIL RESTORATION */
.roofing-layout {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  align-items: center;
  gap: clamp(42px, 7vw, 90px);
}

.roofing-image {
  width: 100%;
  height: 570px;
  object-fit: cover;
  object-position: center;
}

.roofing-copy {
  max-width: 520px;
}

.roofing-copy h2 {
  max-width: 500px;
}

.roofing-copy p {
  line-height: 1.9;
}

.roofing-list {
  display: grid;
  gap: 0;
  margin-top: 28px;
  border-top: 1px solid var(--stone);
}

.roofing-list-item {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding-block: 16px;
  border-bottom: 1px solid var(--stone);
  color: var(--ink);
  font-size: 0.94rem;
  font-weight: 650;
}

.roofing-list-item::before {
  flex: 0 0 auto;
  color: var(--copper);
  content: "—";
}

/* COLORADO ROOFING GUIDE */
.guide-layout {
  display: grid;
  grid-template-columns: 0.8fr 1.2fr;
  align-items: start;
  gap: clamp(45px, 8vw, 110px);
}

.guide-heading {
  max-width: 440px;
}

.guide-heading h2 {
  margin-bottom: 20px;
}

.guide-content {
  border-top: 1px solid rgba(255, 255, 255, 0.23);
}

.guide-step {
  display: grid;
  grid-template-columns: 48px 1fr;
  gap: 20px;
  padding-block: 25px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.23);
}

.guide-step-number {
  color: #e2ad87;
  font-family: var(--font-display);
  font-size: 1.6rem;
}

.guide-step h3 {
  margin-bottom: 8px;
}

.guide-step p {
  max-width: 570px;
  margin-bottom: 0;
}

/* RECENT PROJECTS */
.projects-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 40px;
  margin-bottom: 52px;
}

.projects-heading .section-intro {
  margin-bottom: 0;
}

.project-feature {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  min-height: 470px;
  background: var(--cream);
}

.project-feature-image {
  width: 100%;
  height: 100%;
  min-height: 470px;
  object-fit: cover;
  object-position: center;
}

.project-feature-copy {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: clamp(32px, 5vw, 66px);
}

.project-feature-copy h3 {
  margin-bottom: 15px;
}

.project-feature-copy p {
  max-width: 440px;
  line-height: 1.85;
}

.project-details {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 24px;
  margin-top: 15px;
  color: var(--ink-soft);
  font-size: 0.78rem;
  font-weight: 750;
  letter-spacing: 0.055em;
  text-transform: uppercase;
}

.project-gallery {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  margin-top: 24px;
}

.project-gallery-item {
  position: relative;
  overflow: hidden;
  background: var(--cream);
}

.project-gallery-item img {
  width: 100%;
  height: 340px;
  object-fit: cover;
  transition: transform 450ms ease;
}

.project-gallery-item:hover img {
  transform: scale(1.035);
}

.project-gallery-caption {
  padding: 20px 24px;
  color: var(--ink);
  font-family: var(--font-display);
  font-size: 1.25rem;
}

/* REDUCED MOTION FOUNDATION */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}
