/* CSS PART 2 OF 2 */

/* CONTACT AND CONVERSION */
.contact-section {
  padding-block: clamp(85px, 10vw, 135px);
  background: var(--forest-deep);
  color: var(--white);
}

.contact-layout {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  align-items: start;
  gap: clamp(45px, 8vw, 105px);
}

.contact-copy {
  max-width: 450px;
}

.contact-copy h2 {
  color: var(--white);
}

.contact-copy p {
  color: rgba(255, 255, 255, 0.76);
  line-height: 1.85;
}

.contact-details {
  display: grid;
  gap: 13px;
  margin-top: 35px;
}

.contact-detail {
  color: var(--white);
  font-size: 0.9rem;
  font-weight: 650;
}

.contact-form {
  padding: clamp(25px, 4vw, 48px);
  background: var(--paper);
  color: var(--ink);
  box-shadow: var(--shadow);
}

.form-heading {
  margin-bottom: 28px;
}

.form-heading h3 {
  margin-bottom: 8px;
}

.form-heading p {
  margin-bottom: 0;
  font-size: 0.9rem;
}

.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 21px;
}

.form-field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 8px;
}

.form-field--full {
  grid-column: 1 / -1;
}

.form-field label {
  color: var(--ink);
  font-size: 0.79rem;
  font-weight: 750;
}

.form-field input,
.form-field select,
.form-field textarea {
  width: 100%;
  min-width: 0;
  min-height: 51px;
  padding: 13px 14px;
  border: 1px solid #d8d9d0;
  border-radius: var(--radius);
  background: var(--white);
  color: var(--ink);
  font-size: 0.94rem;
  transition: border-color var(--transition);
}

.form-field textarea {
  min-height: 135px;
  resize: vertical;
}

.form-field input:hover,
.form-field select:hover,
.form-field textarea:hover {
  border-color: var(--sage);
}

.form-field input:focus,
.form-field select:focus,
.form-field textarea:focus {
  border-color: var(--forest);
  outline: 2px solid rgba(41, 63, 53, 0.16);
  outline-offset: 1px;
}

.form-field input::placeholder,
.form-field textarea::placeholder {
  color: #858a82;
}

.form-submit {
  margin-top: 25px;
}

.form-submit .button {
  width: 100%;
}

.form-note {
  margin: 14px 0 0;
  color: #737a72;
  font-size: 0.75rem;
  line-height: 1.6;
}

/* FOOTER */
.site-footer {
  padding-block: 48px 28px;
  background: #17271f;
  color: var(--white);
}

.footer-main {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 35px;
  padding-bottom: 35px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.16);
}

.footer-brand .brand-name {
  color: var(--white);
}

.footer-brand .brand-subtitle {
  color: rgba(255, 255, 255, 0.64);
}

.footer-nav {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 18px 28px;
}

.footer-nav a {
  color: rgba(255, 255, 255, 0.78);
  font-size: 0.8rem;
  transition: color var(--transition);
}

.footer-nav a:hover {
  color: #e2ad87;
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  padding-top: 23px;
  color: rgba(255, 255, 255, 0.57);
  font-size: 0.74rem;
}

/* ACCESSIBLE MOBILE NAVIGATION */
.menu-toggle {
  display: none;
  width: 46px;
  height: 46px;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 5px;
  padding: 0;
  border: 1px solid var(--stone);
  border-radius: var(--radius);
  background: transparent;
  color: var(--forest);
  cursor: pointer;
}

.menu-toggle span[aria-hidden="true"] {
  display: block;
  width: 20px;
  height: 2px;
  flex: 0 0 2px;
  background-color: currentColor;
}

/* RESPONSIVE: TABLET AND SMALL DESKTOP */
@media (max-width: 960px) {
  :root {
    --header-height: 76px;
  }

  .brand-logo {
    width: 56px;
    height: 56px;
  }

  .nav-links {
    gap: 15px;
  }

  .nav-links a:not(.button) {
    font-size: 0.75rem;
  }

  .intro-layout,
  .roofing-layout {
    gap: 38px;
  }

  .intro-image-wrap,
  .intro-image {
    min-height: 390px;
  }

  .roofing-image {
    height: 490px;
  }

  .why-layout,
  .guide-layout {
    gap: 45px;
  }

  .contact-layout {
    gap: 40px;
  }
}

/* RESPONSIVE: MOBILE NAVIGATION */
@media (max-width: 760px) {
  :root {
    --gutter: 23px;
    --header-height: 72px;
  }

  .header-inner {
    position: relative;
    min-height: var(--header-height);
    gap: 12px;
  }

  .brand {
    gap: 10px;
  }

  .brand-logo {
    width: 49px;
    height: 49px;
  }

  .brand-name {
    font-size: 0.98rem;
  }

  .brand-subtitle {
    font-size: 0.56rem;
  }

  .menu-toggle {
    display: flex;
  }

  .nav-links {
    display: none;
    position: absolute;
    z-index: 30;
    top: calc(100% + 1px);
    right: 0;
    left: 0;
    max-height: calc(100svh - var(--header-height) - 15px);
    flex-direction: column;
    align-items: stretch;
    justify-content: flex-start;
    gap: 0;
    overflow-y: auto;
    padding: 12px 20px 20px;
    border: 1px solid var(--stone);
    background: var(--paper);
    box-shadow: var(--shadow);
  }

  .nav-links.is-open {
    display: flex;
  }

  .nav-links a:not(.button) {
    display: block;
    padding: 14px 2px;
    border-bottom: 1px solid var(--stone);
    font-size: 0.88rem;
  }

  .nav-links a:not(.button)::after {
    display: none;
  }

  .nav-links .button {
    width: 100%;
    margin-top: 15px;
  }

  /* HERO */
  .hero {
    min-height: 690px;
    min-height: min(760px, calc(100svh - var(--header-height)));
    align-items: flex-end;
  }

  .hero-image {
    object-position: 57% center;
  }

  .hero::before {
    background:
      linear-gradient(
        0deg,
        rgba(19, 33, 26, 0.94) 0%,
        rgba(19, 33, 26, 0.79) 43%,
        rgba(19, 33, 26, 0.2) 100%
      );
  }

  .hero-content {
    padding-block: 100px 62px;
  }

  .hero h1 {
    font-size: clamp(2.8rem, 11vw, 4.6rem);
  }

  .hero-description {
    font-size: 1rem;
  }

  .hero-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .hero-actions .button {
    width: 100%;
  }

  /* SHARED SECTIONS */
  .section {
    padding-block: 76px;
  }

  .section-intro {
    margin-bottom: 36px;
  }

  h2 {
    font-size: clamp(2.35rem, 9vw, 3.3rem);
  }

  .lead {
    font-size: 1rem;
  }

  /* INTRODUCTION */
  .intro-layout {
    grid-template-columns: 1fr;
    gap: 35px;
  }

  .intro-image-wrap {
    min-height: 0;
  }

  .intro-image {
    height: 370px;
    min-height: 0;
  }

  .intro-caption {
    right: 0;
    bottom: 0;
    max-width: 220px;
    padding: 16px 18px;
